 func (c *AllServersCache) isExpired() bool {
 	maxAge := c.MaxAge
 	if maxAge == 0 {
 		maxAge = 10 * time.Minute
 	}
 	return time.Now().After(c.lastRefresh.Add(maxAge))
 }

