 	req, err := c.client.NewRequest(
 		ctx,
 		"GET",
 		fmt.Sprintf("%s/actions?%s", c.getBaseURL(), opts.values().Encode()),
 		nil,
 	)
 	if err != nil {
 		return nil, nil, err
 	}

 	var body schema.ActionListResponse
 	resp, err := c.client.Do(req, &body)
 	if err != nil {
 		return nil, nil, err
 	}
